const TITLES=['Inicio y pregunta retadora','¿Qué es el diagrama de recorrido?','Un ejemplo de todos los días','Cómo medir en el plano','Kit escolar · hazlo tú','Comprueba lo aprendido','El caso Calzados del Caribe','Capellada · constrúyela','Suela · construye la ruta','Ensamble hasta almacén','Reúne y analiza las rutas','Mejora la distribución','Lleva tu trabajo a Draw.io','IA · tres prompts maestros','Informe, revisión y descargas'];
const KEY='AulaEscena_Lab4_Recorrido_V3';
const STATIONS={CU:{name:'Corte de cuero',x:2,y:2,w:4,h:3},CO:{name:'Costura',x:10,y:2,w:4,h:3},SU:{name:'Corte y preparación de suela',x:2,y:11,w:5,h:4},EN:{name:'Ensamble',x:18,y:6,w:4,h:4},AC:{name:'Acabado',x:24,y:2,w:4,h:3},EM:{name:'Empaque',x:24,y:12,w:4,h:3},PT:{name:'Producto terminado',x:17,y:12,w:4,h:3}};
const KIT_STATIONS={RE:{name:'Reunión',x:1,y:1,w:2,h:2},EM:{name:'Empaque',x:8,y:1,w:2,h:2},PT:{name:'Estante',x:8,y:7,w:2,h:2}};
const ROUTE_META={'CA-03':['CU','CO'],'CA-06':['CO','EN'],'SU-04':['SU','EN'],'ZA-04':['EN','AC'],'ZA-08':['AC','EM'],'ZA-11':['EM','PT'],'KT-03':['RE','EM'],'KT-07':['EM','PT']};
const STAGE_CFG={kit:{name:'Kit escolar',title:'Kit escolar · construye tu primer diagrama',intro:'Coloca las ocho actividades del cursograma sobre el plano. En los transportes, indica el destino y el sistema dibujará el camino para que puedas observar el movimiento.',items:KITEMS.map(e=>({id:'KT-'+String(e.n).padStart(2,'0'),label:e.a,type:e.type,place:e.place,from:e.from,time:e.time})),color:'#176B80'},cap:{name:'Capellada',title:'Ruta 1. Sigue la capellada',intro:'Primero representa las operaciones e inspecciones en corte y costura; después registra los dos transportes hasta ensamble.',items:EVENTS.cap.map(e=>({id:e[0],label:e[1],type:e[2],place:e[3],time:e[4],from:e[5]})),color:'#176B80'},sole:{name:'Suela',title:'Ruta 2. Sigue la suela',intro:'La suela se prepara de manera independiente. Coloca sus tres actividades de trabajo y traza su llegada a ensamble.',items:EVENTS.sole.map(e=>({id:e[0],label:e[1],type:e[2],place:e[3],time:e[4],from:e[5]})),color:'#C4973D'},shoe:{name:'Zapato',title:'Ruta 3. Desde ensamble hasta el almacén',intro:'Después de converger los componentes, representa las doce actividades del zapato hasta su almacenamiento, incluidos tres transportes.',items:EVENTS.shoe.map(e=>({id:e[0],label:e[1],type:e[2],place:e[3],time:e[4],from:e[5]})),color:'#344b6b'}};
const Q=[{q:'¿Para qué se realiza un diagrama de recorrido?',o:['Para mostrar por dónde se desplaza el objeto estudiado','Para calcular el precio del producto','Para reemplazar el cursograma analítico'],a:0,why:'El diagrama ubica actividades y movimientos sobre un plano físico.'},{q:'¿Qué símbolo corresponde a la inspección?',o:['Círculo','Cuadrado','Triángulo'],a:1,why:'El cuadrado representa inspección; el círculo es operación.'},{q:'Si el paquete se inspecciona en la mesa donde se empacó, ¿siempre hay un transporte nuevo?',o:['Sí','No','Solo cuando se mide el tiempo'],a:1,why:'No se registra transporte si el material permanece en el mismo puesto.'},{q:'Antes de dibujar un transporte debes identificar...',o:['Origen, destino y paso disponible','Solamente el tiempo','Únicamente el destino'],a:0,why:'Hay que conocer el origen, el destino y un camino físicamente posible.'},{q:'Un camino mide 2 metros y después otros 3. ¿Cuál es la distancia recorrida?',o:['1 metro','6 metros','5 metros'],a:2,why:'La distancia es la suma de los tramos: 2+3=5 metros.'}];
const DEFAULT={scene:0,name:'',intro:-1,measure:-1,quiz:{},conceptAnswer:'',progress:{kit:{step:0,marks:[],routes:{},waypoint:null},cap:{step:0,marks:[],routes:{},waypoint:null},sole:{step:0,marks:[],routes:{},waypoint:null},shoe:{step:0,marks:[],routes:{},waypoint:null}},feedback:'',selectedStage:'',routeFocus:'',diagnosis:'',hypothesis:'',proposal:'new',proposalText:'',distA:'',distB:'',crossA:'',crossB:'',aiNotes:'',answers:['','','',''],fileCheck:''};
const S=load();let images={drawA:null,drawB:null};let animReq=0;
function load(){try{const v=JSON.parse(localStorage.getItem(KEY));const s=JSON.parse(JSON.stringify(DEFAULT));if(v){Object.assign(s,v);s.progress={...s.progress,...v.progress};for(const k of Object.keys(s.progress))s.progress[k]={...DEFAULT.progress[k],...v.progress?.[k]};}return s}catch{return JSON.parse(JSON.stringify(DEFAULT))}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch{}}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function short(n){return Number(n).toLocaleString('es-CO',{maximumFractionDigits:2})}
function showMsg(t,bad=false){const e=document.getElementById('toast');e.textContent=t;e.style.background=bad?'#a33d38':'#112A46';e.style.display='block';clearTimeout(showMsg.timer);showMsg.timer=setTimeout(()=>e.style.display='none',3500)}
function ready(){return S.name.trim().length>=4}
function go(index){if(index<0||index>=TITLES.length)return;if(index>0&&!ready()){showMsg('Registra primero tu nombre y apellido.',true);index=0}S.scene=index;S.feedback='';save();render();window.scrollTo({top:0,behavior:'instant'})}
function head(i,title,desc){return `<div class="eyeline">ESCENA ${i+1} · LABORATORIO 4</div><h2>${title}</h2><p class="lead">${desc}</p>`}
function fileLink(name,label){return `<a class="btn line" href="assets/${encodeURIComponent(name)}" download>↓ ${esc(label)}</a>`}
function external(url,label){return `<a class="btn gold" href="${url}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`}
function render(){if(animReq)cancelAnimationFrame(animReq);const n=document.getElementById('nav');n.innerHTML=TITLES.map((t,i)=>`<button type="button" data-go="${i}" class="${i===S.scene?'active':''}"><span class="navnum">${i+1}</span><span>${esc(t)}</span></button>`).join('');document.getElementById('progressText').textContent=`${S.scene+1} / ${TITLES.length}`;document.getElementById('progressFill').style.width=`${((S.scene+1)/TITLES.length)*100}%`;document.getElementById('topUser').textContent=ready()?S.name:'Aprendizaje aplicado';document.getElementById('screen').innerHTML=SCENES[S.scene]();document.getElementById('prev').disabled=S.scene===0;document.getElementById('next').disabled=S.scene===TITLES.length-1;document.getElementById('bottomIndex').textContent=`Escena ${S.scene+1} de ${TITLES.length}`;document.title=`${TITLES[S.scene]} · Laboratorio 4`;}
function s0(){return `<div class="hero"><div class="phase-label" style="color:#f4d18b">MÉTODOS Y TIEMPOS · INGENIERÍA INDUSTRIAL</div><h2 style="font-size:clamp(32px,4vw,55px)">Diagrama de recorrido</h2><p style="font-size:19px;max-width:690px">¿Una empresa puede estar trabajando bien y, aun así, mover sus materiales demasiado?</p><p>Aprende con un ejemplo cotidiano, construye el diagrama del kit escolar, estudia las tres rutas de una planta de calzado y después formaliza tu trabajo en Draw.io.</p><div class="field" style="max-width:440px"><label for="name" style="color:white">Nombre y apellidos del estudiante · obligatorio</label><input id="name" value="${esc(S.name)}" autocomplete="name" placeholder="Escribe tu nombre completo"></div><button id="start" class="btn gold">Comenzar laboratorio →</button></div><div class="grid3" style="margin-top:16px"><div class="card"><h3>1. Comprende</h3><p>Concepto, símbolos y escala con ejemplos que conoces.</p></div><div class="card"><h3>2. Construye</h3><p>Ubica actividades y dibuja recorridos en la misma plataforma.</p></div><div class="card"><h3>3. Aplica</h3><p>Transfiere tu trabajo a Draw.io, revísalo con IA y descárgalo.</p></div></div>`}
function s1(){return head(1,'¿Qué es el diagrama de recorrido?','Primero comprende la herramienta: después aprenderás a construirla.')+`<div class="grid"><section class="card"><h3>Una definición clara</h3><p>El <strong>diagrama de recorrido</strong> representa sobre un <strong>plano del lugar de trabajo</strong> dónde ocurren las actividades y por dónde se desplazan materiales, personas o equipos durante un proceso.</p><p>Permite reconocer recorridos extensos, retrocesos, cruces y oportunidades de mejorar la distribución de los puestos.</p><div class="hint">El cursograma analítico dice <b>qué ocurre</b> y en qué orden. El diagrama de recorrido muestra <b>dónde ocurre</b> y el camino que sigue lo estudiado.</div></section><section class="card"><h3>¿Qué debemos dibujar?</h3><div class="stack"><div>◯ <b>Operación</b>: transformación o preparación.</div><div>→ <b>Transporte</b>: desplazamiento de origen a destino.</div><div>□ <b>Inspección</b>: comprobación.</div><div>ᴅ <b>Espera</b>: demora registrada.</div><div>▽ <b>Almacenamiento</b>: guardar el producto.</div></div><p class="muted">Los símbolos se ubican en el plano y las flechas muestran el movimiento. Una operación o inspección puede suceder sin cambiar de estación.</p></section></div><div class="card" style="margin-top:16px"><h3>¿Qué diferencia a los dos diagramas?</h3><div class="tblwrap"><table><tr><th>Cursograma analítico</th><th>Diagrama de recorrido</th></tr><tr><td>Registra la secuencia y las categorías de actividad</td><td>Ubica esas actividades sobre un plano</td></tr><tr><td>Puede registrar tiempos y distancias</td><td>Ayuda a observar la trayectoria y medir recorridos</td></tr><tr><td>Explica qué le sucede al material</td><td>Explica por dónde pasa el material</td></tr></table></div></div>`}
function s2(){const choices=[['Tomar el vaso','Punto de preparación','O'],['Revisar que esté limpio','Punto de preparación','I'],['Llevarlo hasta la mesa','Mesa','T'],['Servir el agua','Mesa','O'],['Llevarlo a la persona','Zona de entrega','T']];return head(2,'De una actividad al plano: un vaso de agua','Antes del caso industrial, observa un proceso sencillo que cualquiera puede reconocer: preparar y entregar un vaso de agua.')+`<div class="scenesplit"><div class="card"><h3>Proceso cotidiano</h3><p>Una persona toma un vaso limpio, lo revisa, lo lleva a una mesa, sirve agua y finalmente lo entrega. Identifica en qué lugares sucede cada actividad.</p><div class="stack">${choices.map((a,i)=>`<button class="step-item ${S.intro===i?'selected':''}" data-simple="${i}"><b>${i+1}. ${a[0]}</b> <span class="pill">${TYPES[a[2]]}</span></button>`).join('')}</div><div class="help-step">Selecciona las actividades y observa cómo la secuencia se sitúa sobre un plano sencillo.</div></div><div class="stack"><div class="card"><h3>Plano ilustrativo · no a escala</h3>${simpleSVG(S.intro)}<div class="hint" style="margin-top:10px">${S.intro<0?'Elige una actividad para ubicarla sobre el plano.':choices[S.intro][2]==='T'?`Actividad ${S.intro+1}: se necesita una flecha de transporte hacia ${choices[S.intro][1]}.`:`Actividad ${S.intro+1}: ocurre en ${choices[S.intro][1]}; no implica un transporte nuevo.`}</div></div><div class="card"><h3>Comprobación</h3><p>¿Revisar el vaso en el mismo punto donde se toma exige dibujar otro transporte?</p><div class="row"><button class="btn line sm" data-simplequiz="si">Sí</button><button class="btn line sm" data-simplequiz="no">No</button></div><p id="simpleFeedback" class="tiny"></p></div></div></div>`}
function simpleSVG(selected){let labels=['Preparación','Mesa','Entrega'];let pts=[[50,95],[200,95],[365,95]];let s=`<svg viewBox="0 0 520 180" style="width:100%;height:auto" role="img" aria-label="Plano de preparación, mesa y entrega"><rect width="520" height="180" rx="8" fill="#f7f4ec"/>`;labels.forEach((l,i)=>{let [x,y]=pts[i];let chosen=selected>=0?([0,1].includes(selected)?0:[2,3].includes(selected)?1:2):null; s+=`<rect x="${x}" y="${y-45}" width="110" height="80" rx="6" fill="${chosen===i?'#d6e8e7':'#fff'}" stroke="${chosen===i?'#176B80':'#b7c9c9'}" stroke-width="${chosen===i?3:1.5}"/><text x="${x+55}" y="${y-4}" text-anchor="middle" font-size="13" fill="#112A46">${l}</text>`});if(selected===2)s+=`<path d="M160 90 H200" stroke="#176B80" stroke-width="4" marker-end="url(#arrowSimple)"/>`;if(selected===4)s+=`<path d="M310 90 H365" stroke="#176B80" stroke-width="4" marker-end="url(#arrowSimple)"/>`;s+=`<defs><marker id="arrowSimple" markerWidth="9" markerHeight="9" refX="7" refY="3" orient="auto"><path d="M0 0 L7 3 L0 6Z" fill="#176B80"/></marker></defs><text x="260" y="155" fill="#61717b" text-anchor="middle" font-size="11">Actividades numeradas → transportes con flechas</text></svg>`;return s}
function s3(){return head(3,'Aprende a medir distancias sobre el plano','La planta industrial simulada tendrá 30 × 18 metros. Cada cuadrito pequeño de su plano representa 0,5 m.')+`<div class="grid"><div class="card"><h3>¿Qué significa la escala?</h3><p>Dos cuadritos de 0,5 m equivalen a <b>1 metro</b>. Ocho cuadritos equivalen a <b>4 metros</b>.</p>${rulerSVG()}<div class="hint">Los 30 × 18 m y las posiciones de los equipos son datos inventados <b>solo para enseñar</b>. No provienen de mediciones de una fábrica real.</div></div><div class="card"><h3>El camino no siempre es recto</h3><p>Si una máquina bloquea la línea directa, el material debe rodearla. La distancia se calcula sumando cada tramo disponible, no atravesando equipos.</p>${scaleDetour()}<p><b>Ejemplo:</b> 3 m + 2 m = 5 m de recorrido.</p><div class="field"><label>Comprueba: 4 m + 3 m = ?</label><div class="row">${['5','7','12'].map(x=>`<button data-measure="${x}" class="btn ${String(S.measure)===x?'navy':'line'} sm">${x} m</button>`).join('')}</div></div><button id="checkMeasure" class="btn sm" ${S.measure<0?'disabled':''}>Comprobar</button><div id="measureFeedback">${S.measureChecked?`<div class="${S.measure===7?'good':'hint'}">${S.measure===7?'Correcto: son 7 metros.':'Revisa la suma de los dos tramos.'}</div>`:''}</div></div></div>`}
function rulerSVG(){return `<svg viewBox="0 0 390 120" style="width:100%;height:auto" role="img" aria-label="Cuadrícula: ocho cuadros de 0,5 m equivalen a cuatro metros"><rect width="390" height="120" fill="white"/>${Array.from({length:9},(_,i)=>`<line x1="${35+i*40}" y1="13" x2="${35+i*40}" y2="75" stroke="#aec6cc"/>`).join('')}<path d="M35 45 H355" stroke="#176B80" stroke-width="5"/><circle cx="35" cy="45" r="5" fill="#112A46"/><circle cx="355" cy="45" r="5" fill="#112A46"/><path d="M35 85 H115 M35 82 V90 M115 82 V90" stroke="#D6A84B" stroke-width="3"/><text x="75" y="104" text-anchor="middle" font-size="12" fill="#112A46">2 = 1 m</text><text x="240" y="104" text-anchor="middle" font-size="12" fill="#176B80" font-weight="bold">8 divisiones = 4 m</text></svg>`}
function scaleDetour(){return `<svg viewBox="0 0 340 155" style="width:100%;height:auto" role="img" aria-label="Ruta de 3 metros horizontales y 2 verticales alrededor de una máquina"><rect width="340" height="155" fill="#f8faf9"/><rect x="120" y="67" width="85" height="62" rx="4" fill="#e5e9ed" stroke="#778c98"/><text x="163" y="100" font-size="11" fill="#303A46" text-anchor="middle">Máquina</text><path d="M53 133 V29 H263" fill="none" stroke="#176B80" stroke-width="5"/><path d="M252 23 L264 29 L252 35" fill="none" stroke="#176B80" stroke-width="3"/><circle cx="53" cy="133" r="12" fill="#176B80"/><text x="53" y="137" font-size="11" fill="white" text-anchor="middle">A</text><circle cx="264" cy="29" r="12" fill="#D6A84B"/><text x="264" y="33" font-size="11" fill="#112A46" text-anchor="middle">B</text><text x="26" y="87" font-size="12" fill="#176B80">2 m</text><text x="151" y="20" font-size="12" fill="#176B80">3 m</text></svg>`}
// Geometría: coordenadas expresadas en metros; cuadrícula 0,5 m.
const ROUTE_PORTS={
 'CA-03':[[6.5,4.5],[9.5,4.5]],'CA-06':[[14.5,4.5],[17.5,8.5]],
 'SU-04':[[7.5,13],[17.5,8.5]],'ZA-04':[[22.5,8.5],[23.5,3.5]],
 'ZA-08':[[26,5.5],[26,11.5]],'ZA-11':[[23.5,13.5],[21.5,13.5]],
 'KT-03':[[3.5,2],[7.5,2]],'KT-07':[[9,3.5],[9,6.5]]};
function stationsFor(kind,proposal=false){if(kind==='kit')return KIT_STATIONS;const st=structuredClone(STATIONS);if(proposal)st.AC.y=7;return st}
function endpoints(code,proposal=false){const ep=ROUTE_PORTS[code];if(!ep)return null;if(!proposal)return ep;let [a,b]=ep.map(x=>x.slice());if(code==='ZA-04')b=[23.5,8.5];if(code==='ZA-08')a=[26,10.5];return [a,b]}
function pointIsFree(x,y,stationMap,maxX,maxY){if(x<=0||x>=maxX||y<=0||y>=maxY)return false;return !Object.values(stationMap).some(s=>x>=s.x-.15&&x<=s.x+s.w+.15&&y>=s.y-.15&&y<=s.y+s.h+.15)}
// Recorrido ortogonal calculado: penaliza ligeramente los giros para evitar zigzags.
function pathSearch(start,end,stationMap,maxX=30,maxY=18){const toCell=p=>p.map(v=>Math.round(v*2));const [sx,sy]=toCell(start),[tx,ty]=toCell(end);const key=(x,y,d)=>`${x},${y},${d}`;const q=[{x:sx,y:sy,d:4,c:0,g:0,k:key(sx,sy,4)}],seen=new Map(),prev=new Map();seen.set(q[0].k,0);const moves=[[1,0],[0,1],[-1,0],[0,-1]];let done=null,iterations=0;while(q.length&&iterations++<35000){q.sort((a,b)=>a.c-b.c);const z=q.shift();if(z.g!==seen.get(z.k))continue;if(z.x===tx&&z.y===ty){done=z;break}for(let d=0;d<4;d++){let x=z.x+moves[d][0],y=z.y+moves[d][1],mx=x/2,my=y/2;if(!pointIsFree(mx,my,stationMap,maxX,maxY))continue;const nk=key(x,y,d);const ng=z.g+.5+(z.d!==4&&z.d!==d?.07:0);if(ng<(seen.get(nk)??Infinity)){seen.set(nk,ng);prev.set(nk,z.k);q.push({x,y,d,c:ng+Math.abs(tx-x)*.5+Math.abs(ty-y)*.5,g:ng,k:nk})}}}
 if(!done)return null;const points=[];let k=done.k;while(k){const [x,y]=k.split(',').map(Number);points.push([x/2,y/2]);k=prev.get(k)}points.reverse();let sparse=[points[0]];for(let i=1;i<points.length-1;i++){const a=points[i-1],b=points[i],c=points[i+1];if(Math.sign(b[0]-a[0])!==Math.sign(c[0]-b[0])||Math.sign(b[1]-a[1])!==Math.sign(c[1]-b[1]))sparse.push(b)}sparse.push(points.at(-1));const clean=sparse.filter((p,i)=>!i||p[0]!==sparse[i-1][0]||p[1]!==sparse[i-1][1]);return{pts:clean,dist:(points.length-1)*.5}}
function calculatePath(code,waypoint=null,proposal=false,kind='industrial'){const ep=endpoints(code,proposal),st=stationsFor(kind==='kit'?'kit':'industrial',proposal),xx=kind==='kit'?12:30,yy=kind==='kit'?10:18;if(!ep)return null;if(!waypoint)return pathSearch(ep[0],ep[1],st,xx,yy);const a=pathSearch(ep[0],waypoint,st,xx,yy),b=pathSearch(waypoint,ep[1],st,xx,yy);if(!a||!b)return null;return{pts:[...a.pts,...b.pts.slice(1)],dist:a.dist+b.dist}}
function stageState(k){return S.progress[k]}
function stageTotal(k){return Object.values(stageState(k).routes).reduce((s,v)=>s+(v.dist||0),0)}
function allRoutes(){return Object.assign({},...['cap','sole','shoe'].map(k=>stageState(k).routes))}
function actualDist(){return ['cap','sole','shoe'].reduce((n,k)=>n+stageTotal(k),0)}
function countCompleted(k){return stageState(k).step}
function stagesComplete(){return ['cap','sole','shoe'].every(k=>stageState(k).step===STAGE_CFG[k].items.length)}
function resultForProposal(){if(!stagesComplete())return null;let m={};for(const code of Object.keys(allRoutes()))m[code]=calculatePath(code,null,S.proposal==='new');return m}
const COLOR={kit:'#176B80',cap:'#176B80',sole:'#B78728',shoe:'#3B5877'};
function diagramSVG(mode='kit',opts={}){
 const kit=mode==='kit',w=kit?12:30,h=kit?10:18,s=kit?44:28,offx=kit?34:50,offy=kit?38:57,W=offx+w*s+25,H=offy+h*s+39,st=stationsFor(mode,!!opts.proposal);
 const routeGroups=kit?{kit:stageState('kit').routes}:opts.proposal?{cap:{},sole:{},shoe:{}}:opts.merge?{cap:stageState('cap').routes,sole:stageState('sole').routes,shoe:stageState('shoe').routes}:{[mode]:stageState(mode).routes};
 if(opts.proposal){const proposed=resultForProposal()||{};for(const [code,v] of Object.entries(proposed)){const k=code.startsWith('CA')?'cap':code.startsWith('SU')?'sole':'shoe';if(v)routeGroups[k][code]=v}}
 const marks=kit?stageState('kit').marks:opts.merge||opts.proposal?['cap','sole','shoe'].flatMap(k=>stageState(k).marks):stageState(mode).marks;
 const active=!opts.merge&&!opts.proposal?STAGE_CFG[mode].items[stageState(mode).step]:null;
 let out=`<svg class="plan-svg" viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Diagrama de recorrido, ${kit?'kit escolar':'planta de calzado'}, con estaciones y actividades"><rect width="${W}" height="${H}" fill="#FFFFFF"/>`;
 out+=`<rect x="${offx}" y="${offy}" width="${w*s}" height="${h*s}" fill="#fbfcfa" stroke="#112A46" stroke-width="3"/>`;
 for(let x=0;x<=w;x+=.5)out+=`<line x1="${offx+x*s}" y1="${offy}" x2="${offx+x*s}" y2="${offy+h*s}" stroke="${x%1===0?'#d0dfdf':'#ebf1f0'}" stroke-width="${x%1===0?1:.6}"/>`;
 for(let y=0;y<=h;y+=.5)out+=`<line x1="${offx}" y1="${offy+y*s}" x2="${offx+w*s}" y2="${offy+y*s}" stroke="${y%1===0?'#d0dfdf':'#ebf1f0'}" stroke-width="${y%1===0?1:.6}"/>`;
 for(let x=0;x<=w;x+=kit?2:5)out+=`<text x="${offx+x*s}" y="${offy-10}" fill="#607382" font-size="11" text-anchor="middle">${x}</text>`;
 for(let y=0;y<=h;y+=kit?2:3)out+=`<text x="${offx-10}" y="${offy+y*s+4}" fill="#607382" font-size="11" text-anchor="end">${y}</text>`;
 out+=`<rect x="${offx}" y="${offy}" width="${w*s}" height="${h*s}" fill="transparent" data-mapbg="${mode}"/>`;
 const linePath=(points)=>points.map((p,i)=>`${i?'L':'M'}${(offx+p[0]*s).toFixed(1)} ${(offy+p[1]*s).toFixed(1)}`).join(' ');
 for(const [k,routes] of Object.entries(routeGroups)){const color=COLOR[k]||'#176B80';out+=`<defs><marker id="arr_${k}_${mode}_${opts.proposal?'proposed':'current'}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="${color}"/></marker></defs>`;for(const [code,route] of Object.entries(routes)){if(!route?.pts?.length)continue;const pth=linePath(route.pts);out+=`<path id="drawroute_${code}" data-code="${code}" d="${pth}" fill="none" stroke="${color}" stroke-width="${kit?4:3.7}" stroke-linejoin="round" stroke-linecap="round" marker-end="url(#arr_${k}_${mode}_${opts.proposal?'proposed':'current'})"/>`;let pts=route.pts,pt=pts[Math.floor(pts.length/2)];out+=`<rect x="${offx+pt[0]*s-24}" y="${offy+pt[1]*s-13}" width="48" height="18" rx="5" fill="white" opacity=".96"/><text x="${offx+pt[0]*s}" y="${offy+pt[1]*s}" text-anchor="middle" font-size="${kit?11:10}" font-weight="bold" fill="${color}">${esc(code)} · ${short(route.dist)}m</text>`}}
 // Clickable areas and schematic machines
 Object.entries(st).forEach(([id,a])=>{let X=offx+a.x*s,Y=offy+a.y*s;let selected=active?.place===id;out+=`<g data-area="${id}" role="button" tabindex="0" aria-label="Seleccionar ${esc(a.name)}"><rect class="area-shape" x="${X}" y="${Y}" width="${a.w*s}" height="${a.h*s}" rx="7" fill="${selected?'#e8f3f5':'#e6eef0'}" stroke="${selected?'#d6a84b':'#176B80'}" stroke-width="${selected?3:2}"/><text pointer-events="none" x="${X+a.w*s/2}" y="${Y+17}" text-anchor="middle" font-size="${kit?14:12}" font-weight="bold" fill="#112A46">${esc(kit?a.name:(id+' · '+(a.name.length>16?a.name.slice(0,15)+'…':a.name)))}</text>`;if(!kit){out+=`<rect pointer-events="none" x="${X+10}" y="${Y+25}" width="${Math.max(20,(a.w*s)-20)}" height="${Math.max(9,Math.min(20,a.h*s-32))}" fill="#c9d5da" stroke="#8da1a9"/>`;}out+=`</g>`});
 // Markers for operations / inspections / delays / storage, numbers preserved
 let grouped={};for(const m of marks){if(m.type==='T')continue;(grouped[m.place]??=[]).push(m)}
 for(const [id,ls] of Object.entries(grouped)){const a=st[id];if(!a)continue;ls.forEach((m,j)=>{let X=offx+(a.x+.15)*s,Y=offy+(a.y+(kit?.92:1.3))*s+j*18;const sym=m.type==='O'?'◯':m.type==='I'?'□':m.type==='E'?'ᴅ':'▽';out+=`<rect pointer-events="none" x="${X-3}" y="${Y-13}" rx="3" width="${kit?72:74}" height="17" fill="white" opacity=".94"/><text pointer-events="none" x="${X}" y="${Y}" fill="#112A46" font-size="${kit?11:10}" font-weight="700">${sym} ${esc(m.id)}</text>`})}
 if(active?.type==='T'){const ep=endpoints(active.id);if(ep){out+=`<circle cx="${offx+ep[0][0]*s}" cy="${offy+ep[0][1]*s}" r="7" fill="#21916e" stroke="white" stroke-width="2"/><text x="${offx+ep[0][0]*s+11}" y="${offy+ep[0][1]*s-10}" font-size="10" fill="#166e55" font-weight="bold">INICIO</text>`}}
 const waypoint=stageState(mode)?.waypoint;if(!opts.merge&&!opts.proposal&&waypoint&&active?.type==='T'){out+=`<circle cx="${offx+waypoint[0]*s}" cy="${offy+waypoint[1]*s}" r="8" fill="#D6A84B" stroke="#112A46" stroke-width="2"/><text x="${offx+waypoint[0]*s+12}" y="${offy+waypoint[1]*s-9}" font-size="10" fill="#112A46">Punto de paso</text>`}
 out+=`<text x="${W/2}" y="${H-12}" fill="#61717b" text-anchor="middle" font-size="11">${kit?'Kit: 12 × 10 m · cuadrícula 0,5 m':'Planta didáctica: 30 × 18 m · cuadrícula 0,5 m'} · Mg. Vicky Ruiz</text></svg>`;return out;
}
function stagePanel(k){const cfg=STAGE_CFG[k],p=stageState(k),item=cfg.items[p.step],done=p.step>=cfg.items.length,transport=item?.type==='T';return `<div class="stack"><div class="card"><div class="row between"><h3>${k==='kit'?'Ahora hazlo tú':'Actividades por representar'}</h3><span class="pill">${p.step} / ${cfg.items.length}</span></div><div class="progress-mini">${cfg.items.map((x,i)=>`<span class="${i<p.step?'done':i===p.step?'focus':''}">${x.id}</span>`).join('')}</div><div class="current-step" style="margin-top:14px">${done?`<b>¡Diagrama completo!</b><p>Has ubicado ${cfg.items.length} actividades y dibujado ${Object.keys(p.routes).length} transportes.</p>`:`<span class="tiny">ACTIVIDAD ${p.step+1} DE ${cfg.items.length} · ${TYPES[item.type]}</span><h3 style="margin:6px 0">${esc(item.id)} · ${esc(item.label)}</h3><p style="margin:6px 0">${transport?'Esta es una actividad de TRANSPORTE. Haz clic en la estación a la que llega el material. La ruta aparecerá sobre el plano.':'Selecciona en el plano la estación donde se realiza esta actividad para colocar su símbolo numerado.'}</p>`}</div>${!done&&transport?`<div class="note" style="margin-top:10px"><b>Para explorar otra trayectoria:</b> puedes pulsar un lugar libre del pasillo para fijar un punto de paso y luego seleccionar el destino. Si no marcas uno, el sistema dibuja el camino transitable más corto.</div>`:''}<div id="stageFeedback" class="${S.selectedStage===k&&S.feedback?'hint':'tiny'}" style="margin-top:8px">${S.selectedStage===k?esc(S.feedback):'La aplicación te indicará qué debes corregir.'}</div><div class="map-actions" style="margin-top:12px"><button class="btn line sm" data-undo="${k}" ${p.step===0?'disabled':''}>↶ Deshacer</button><button class="btn line sm" data-hint="${k}" ${done?'disabled':''}>Pista</button>${transport?`<button class="btn soft sm" data-clearp="${k}">Borrar punto de paso</button>`:''}<button class="btn line sm" data-review="${k}">✓ Revisar</button></div><p class="tiny" style="margin-top:9px">${k==='kit'?'Puedes descargar el resultado cuando termines las ocho actividades.':'Cada actividad se registra sobre la planta. Los resultados se conservarán para la vista consolidada.'}</p></div>${p.step?`<div class="card"><h3>Recorridos obtenidos</h3><div class="segment-list">${Object.entries(p.routes).map(([code,v])=>`<div class="row between"><span>${code}</span><b>${short(v.dist)} m</b></div>`).join('')||'<p>Aún no has representado transportes.</p>'}</div><div class="stat" style="margin-top:12px"><small>Total de los transportes trazados</small><strong>${short(stageTotal(k))} m</strong></div>${done?`<div class="map-actions" style="margin-top:10px"><button class="btn line sm" data-export="${k}">↓ Descargar mi plano PNG</button><button class="btn line sm" data-play="${k}">▶ Simular movimiento</button></div>`:''}</div>`:''}</div>`}
function stageScene(k,n){const cfg=STAGE_CFG[k],p=stageState(k);let docs=k==='kit'?`<div class="row">${fileLink('Caso_Kit_Escolar_Cursograma_Analitico_Resuelto.docx','Descargar caso y cursograma en Word')}</div>`:`<div class="row">${fileLink('Caso_Calzados_del_Caribe_3_Cursogramas_Analiticos.docx','Consultar cursogramas en Word')}</div>`;return head(n,cfg.title,cfg.intro)+`<div class="card cream" style="margin-bottom:15px"><div class="row between"><b>${k==='kit'?'Primero consulta el caso y sus ocho actividades.':'Lee la secuencia de esta ruta antes de colocar actividades.'}</b>${docs}</div><p style="margin:8px 0 0">Para trabajar: <b>selecciona una estación en el plano</b>. En los transportes, la herramienta construye y mide la trayectoria; puedes elegir un punto de paso en el pasillo si deseas ensayar otro camino. Observa la animación del material.</p></div><div class="workspace"><section class="card map-card"><h3>${k==='kit'?'Plano de práctica · pedido escolar':'Plano industrial · '+cfg.name}</h3><div class="map-svg-area">${diagramSVG(k)}</div><div class="route-legend"><span><i class="keydot" style="background:${cfg.color}"></i>Recorrido de ${cfg.name}</span><span>◯ Operación &nbsp; □ Inspección &nbsp; → Transporte &nbsp; ▽ Almacén</span></div><p class="caption">Haz clic en cada estación para construir el diagrama; los trayectos solo se dibujan cuando corresponde un transporte.</p></section>${stagePanel(k)}</div><div class="card" style="margin-top:16px"><h3>Cursograma analítico disponible durante la práctica</h3><div class="tblwrap"><table><tr><th>N.º</th><th>Actividad</th><th>Símbolo</th><th>Tiempo</th><th>Estado</th></tr>${cfg.items.map((x,i)=>`<tr><td><b>${x.id}</b></td><td>${esc(x.label)}</td><td>${SYMBOLS[x.type]} ${TYPES[x.type]}</td><td>${x.time==null?'NI':short(x.time)+' min'}</td><td>${i<p.step?'✓ Ubicada':'Pendiente'}</td></tr>`).join('')}</table></div></div>`}
function s4(){return stageScene('kit',4)}
function s5(){return head(5,'Comprueba lo que aprendiste','Estas preguntas utilizan únicamente conceptos que ya estudiaste. Puedes reintentar cada respuesta.')+`<div class="stack">${Q.map((q,i)=>`<section class="card"><div class="row between"><h3>${i+1}. ${q.q}</h3><span class="pill">${S.quiz[i]===undefined?'Sin responder':'Revisada'}</span></div><div class="stack">${q.o.map((v,j)=>`<button class="qopt ${S.quiz[i]===j?'selected':''}" data-quiz="${i}:${j}">${String.fromCharCode(65+j)}. ${v}</button>`).join('')}</div>${S.quiz[i]!==undefined?`<div class="${S.quiz[i]===q.a?'good':'hint'}" style="margin-top:11px">${S.quiz[i]===q.a?'Correcto.':'Esta no es la opción adecuada.'} ${q.why}</div>`:''}</section>`).join('')}</div><div class="card cream" style="margin-top:16px"><b>Respuestas correctas: ${Q.filter((q,i)=>S.quiz[i]===q.a).length} de 5.</b> Puedes repetirlas.</div>`}
function s6(){return head(6,'Conoce Calzados del Caribe S.A.S.','Ahora sí presentamos el caso industrial. Es una empresa ficticia, y su proceso de fabricación está simplificado para el estudio de métodos.')+`<div class="grid"><div class="card"><h3>¿Qué vamos a seguir?</h3><p>Una unidad de zapato de cuero. Antes del ensamble, dos componentes se preparan en paralelo: <b>capellada</b> y <b>suela</b>. Luego se unen y el zapato pasa por acabado, empaque y almacenamiento.</p><div class="grid3"><div class="stat"><small>Capellada</small><strong>6</strong><small>actividades · 2 transportes</small></div><div class="stat"><small>Suela</small><strong>4</strong><small>actividades · 1 transporte</small></div><div class="stat"><small>Desde ensamble</small><strong>12</strong><small>actividades · 3 transportes</small></div></div><p class="note" style="margin-top:12px">Los 91 minutos sumados de las actividades no son 91 minutos de duración real del zapato: hay líneas que pueden ejecutarse simultáneamente. El tiempo teórico del caso bajo supuestos específicos fue 76 minutos.</p></div><div class="card"><h3>La estructura de las rutas</h3>${branchSVG()}<p>En las escenas siguientes representarás las tres rutas <b>dentro de esta plataforma</b>, antes de trabajar con Draw.io.</p>${fileLink('Caso_Calzados_del_Caribe_3_Cursogramas_Analiticos.docx','Descargar caso y tres cursogramas')}</div></div><div class="card" style="margin-top:16px"><h3>¿Cómo deberían representarse las dos ramas iniciales?</h3><div class="row"><button class="btn line sm" data-branches="ok">Como rutas independientes hasta ensamble</button><button class="btn line sm" data-branches="other">Como una sola ruta consecutiva</button></div><div id="branchFeedback" style="margin-top:10px"></div></div>`}
function branchSVG(){return `<svg viewBox="0 0 510 210" style="width:100%;height:auto" role="img" aria-label="Capellada y suela avanzan de forma paralela hacia ensamble"><rect width="510" height="210" fill="#f8faf9"/>${[['Capellada',12,25,'#dceff0'],['Suela',12,119,'#fbefd1'],['Ensamble',350,73,'#e4f2ee']].map(([name,x,y,fill])=>`<rect x="${x}" y="${y}" width="132" height="65" rx="10" fill="${fill}" stroke="#176B80" stroke-width="2"/><text x="${x+66}" y="${y+38}" text-anchor="middle" font-weight="bold" font-size="16" fill="#112A46">${name}</text>`).join('')}<path d="M144 58H310V106H350" fill="none" stroke="#176B80" stroke-width="4"/><path d="M144 151H310V114H350" fill="none" stroke="#c39b36" stroke-width="4"/><path d="M339 99L351 106L339 113" fill="none" stroke="#176B80" stroke-width="3"/></svg>`}
const s7=()=>stageScene('cap',7),s8=()=>stageScene('sole',8),s9=()=>stageScene('shoe',9);
function s10(){let complete=stagesComplete(),done=Object.values(S.progress).slice(1).reduce((s,v)=>s+v.step,0),total=22;return head(10,'Consolida los recorridos y estudia la planta','Observa la capellada, la suela y el zapato sobre un mismo plano, sin convertir las ramas iniciales en una secuencia artificial.')+`<div class="workspace wide-plan"><div class="card map-card"><h3>Diagrama de recorrido consolidado</h3>${diagramSVG('cap',{merge:true})}<div class="route-legend"><span><i class="keydot" style="background:#176B80"></i>Capellada</span><span><i class="keydot" style="background:#B78728"></i>Suela</span><span><i class="keydot" style="background:#3B5877"></i>Zapato</span></div><div class="map-actions" style="margin-top:12px"><button class="btn line sm" data-export="consolidated">↓ Descargar plano actual PNG</button><button class="btn line sm" data-play="consolidated">▶ Simular recorridos</button></div></div><div class="stack"><div class="card"><h3>Estado de tu construcción</h3><div class="grid"><div class="stat"><small>Actividades ubicadas</small><strong>${done}/22</strong></div><div class="stat"><small>Distancia sumada</small><strong>${short(actualDist())} m</strong></div></div>${['cap','sole','shoe'].map(k=>`<div class="row between" style="padding:10px 0;border-bottom:1px solid #dce5e6"><span>${STAGE_CFG[k].name}</span><b>${short(stageTotal(k))} m</b></div>`).join('')}<div class="${complete?'good':'note'}" style="margin-top:12px">${complete?'Has representado las 22 actividades y los seis transportes. La distancia corresponde a las rutas construidas sobre esta planta simulada.':'Todavía tienes actividades por construir. Completa las tres rutas antes de comparar el método actual con uno propuesto.'}</div></div><div class="card"><h3>Tu diagnóstico</h3><div class="field"><label for="diagnosis">¿Qué recorridos parecen más extensos y por qué?</label><textarea id="diagnosis" placeholder="Utiliza los resultados de las tres rutas...">${esc(S.diagnosis)}</textarea></div><div class="field"><label for="hypothesis">¿Qué cambio de distribución estudiarías?</label><textarea id="hypothesis" placeholder="Formula una hipótesis, sin afirmar ahorros no medidos...">${esc(S.hypothesis)}</textarea></div></div></div></div>`}
function proposedDist(){const m=resultForProposal();return m?Object.values(m).reduce((s,v)=>s+(v?.dist||0),0):null}
function s11(){const done=stagesComplete(),actual=actualDist(),after=proposedDist(),delta=after===null?null:actual-after,pct=done&&actual>0?delta/actual*100:null;return head(11,'Ensaya una mejora dentro del laboratorio','Antes de utilizar Draw.io, experimenta con una alternativa en esta misma planta. La herramienta recalcula las rutas teniendo en cuenta las estaciones y los pasillos transitables.')+`<div class="card cream" style="margin-bottom:16px"><h3>Decisión de distribución</h3><p>El puesto de acabado puede permanecer en la ubicación inicial o ensayarse en una <b>zona hipotética más cercana a empaque y ensamble</b>. No estamos autorizando físicamente el traslado: antes se comprobarían las conexiones, la ventilación, los accesos y la seguridad.</p><div class="row"><button class="btn ${S.proposal==='same'?'navy':'line'}" data-proposal="same">Mantener posición de acabado</button><button class="btn ${S.proposal==='new'?'navy':'line'}" data-proposal="new">Ensayar acabado en (24 m, 7 m)</button></div></div><div class="workspace"><div class="card map-card"><h3>Distribución propuesta · simulación</h3>${diagramSVG('cap',{proposal:true})}<div class="map-actions" style="margin-top:12px"><button class="btn line sm" data-export="proposed">↓ Descargar plano propuesto PNG</button></div></div><div class="stack"><div class="card"><h3>Comparación calculada</h3>${done?`<div class="two-stat"><div class="stat"><small>Método actual construido</small><strong>${short(actual)} m</strong></div><div class="stat"><small>Propuesta simulada</small><strong>${short(after)} m</strong></div></div><div class="stat" style="margin-top:10px"><small>Variación porcentual</small><strong>${pct===null?'Por calcular':short(pct)+' %'}</strong></div><p class="${delta>0?'good':delta<0?'hint':'note'}">${delta>0?`La propuesta reduce ${short(delta)} metros de recorrido respecto a tus trazados actuales.`:delta<0?`La propuesta aumenta ${short(-delta)} metros. Debes analizar por qué.`:'No se obtiene reducción de distancia con esta alternativa.'}</p>`:`<div class="note">Primero completa las tres rutas en las escenas 8, 9 y 10. Así la comparación será entre tus recorridos, no entre cifras que el sistema haya inventado.</div>`}<p class="tiny">Comparación de distancias en un plano didáctico. No implica automáticamente ahorro de tiempo, dinero o viabilidad industrial.</p></div><div class="card"><h3>Defiende tu decisión</h3><div class="field"><label for="proposalText">¿Recomendarías implementar este cambio? ¿Qué falta comprobar?</label><textarea id="proposalText" placeholder="Describe los resultados y las condiciones pendientes...">${esc(S.proposalText)}</textarea></div></div></div></div>`}
function s12(){return head(12,'Ahora sí: formaliza tu diagrama en Draw.io','Ya practicaste dentro de la plataforma. En esta fase utilizarás un editor profesional para presentar el diagrama industrial con sus símbolos, números y recorridos.')+`<div class="grid"><div class="card stack"><h3>1. Abre tu plantilla editable</h3><p>Descarga el plano con seis páginas: plano base, capellada, suela, zapato desde ensamble, consolidado y método propuesto.</p>${fileLink('Plantilla_Calzados_6_Paginas.drawio','Descargar plantilla .drawio')}${external('https://app.diagrams.net/','Abrir Draw.io en otra pestaña')}<div class="hint">En la pestaña nueva, abre <b>Archivo → Abrir desde → Dispositivo</b> y selecciona el archivo descargado. No necesitas pegar ni buscar código XML para usar la plantilla.</div></div><div class="card stack"><h3>2. Lleva tu trabajo al editor</h3><p>En las páginas de la plantilla, sitúa los símbolos de todas las actividades en sus estaciones y representa los seis transportes con flechas numeradas. Conserva el plano, la escala y las tres rutas independientes hasta ensamble.</p><div class="segment-list"><div>01 · Capellada — 6 actividades y 2 transportes</div><div>02 · Suela — 4 actividades y 1 transporte</div><div>03 · Zapato — 12 actividades y 3 transportes</div><div>04 · Vista consolidada</div><div>05 · Método propuesto, si justificas cambios</div></div><p class="note">No basta con marcar el cursograma como leído: los símbolos y las flechas deben estar realmente dibujados sobre la planta.</p></div></div><div class="card" style="margin-top:16px"><h3>3. Comprueba tu archivo .drawio</h3><p>Sube el archivo editable exportado de Draw.io. Podemos reconocer su estructura y detectar códigos de las actividades, pero <b>la comprobación automática no certifica que las rutas sean físicamente correctas</b>.</p><label class="field"><b>Seleccionar diagrama .drawio</b><input type="file" id="drawioFile" accept=".drawio,.xml,text/xml,application/xml" class="filechoice"></label><div id="fileFeedback">${esc(S.fileCheck)||'<span class="tiny">Aún no has seleccionado ningún archivo.</span>'}</div></div>`}
function s13(){let arr=[['levantamiento','Prompt 1 · Pregunta las medidas y prepara la matriz','Fotografía, plano, cursograma o descripción → datos faltantes y matriz'],['actual','Prompt 2 · Crea el diagrama actual AS-IS','Matriz confirmada → plano y código .drawio'],['mejora','Prompt 3 · Diseña el método mejorado TO-BE','Diagrama actual → alternativas, restricciones y comparación'],['auditoria','Prompt 4 · Auditoría de tu trabajo','Diagramas y evidencias → revisión crítica y correcciones']];return head(13,'Inteligencia artificial: herramientas para cualquier proceso','Estos prompts pueden utilizarse con una fotografía, un croquis, un plano o un cursograma. La IA debe pedir primero las medidas que falten: no tiene permiso de inventarlas.')+`<div class="card cream" style="margin-bottom:16px"><h3>Orden de trabajo recomendado</h3><p><b>Primero:</b> levantamiento de datos. <b>Después:</b> elaboración del recorrido actual. <b>Luego:</b> diseño mejorado. <b>Por último:</b> revisión de la consistencia con la fuente.</p><p>En los prompts encontrarás instrucciones sobre dimensiones, posiciones de máquinas, accesos, rutas paralelas, símbolos ASME y código XML de Draw.io. Úsalos con archivos propios, no con valores inventados.</p></div><div class="stack">${arr.map(([key,t,desc])=>`<details class="card"><summary>${t}</summary><p>${desc}</p><div class="map-actions" style="margin:10px 0"><button class="btn sm" data-prompt="${key}">Copiar prompt completo</button>${external('https://app.diagrams.net/','Abrir Draw.io')}</div><textarea class="prompt-pre" readonly aria-label="Prompt ${esc(t)}">${esc(PROMPTS[key])}</textarea></details>`).join('')}</div><div class="note" style="margin-top:16px"><b>Recuerda:</b> si un plano procede de una fotografía, algunas dimensiones pueden ser estimadas o imposibles de observar. Pide mediciones y verifica cualquier dato que no esté confirmado.</div>`}
function s14(){const done=stageState('kit').step===8,completed=stagesComplete();return head(14,'Revisa y descarga tu informe','Reúne los diagramas construidos dentro del laboratorio, adjunta tus planos finales de Draw.io cuando los tengas, revisa los resultados y redacta tus conclusiones.')+`<div class="grid"><div class="card stack"><h3>1. Descarga las evidencias de la plataforma</h3><div class="map-actions"><button class="btn line sm" data-export="kit" ${done?'':'disabled'}>↓ Kit escolar PNG</button><button class="btn line sm" data-export="consolidated">↓ Planta actual PNG</button><button class="btn line sm" data-export="proposed">↓ Planta propuesta PNG</button></div><div class="grid"><div class="stat"><small>Kit escolar</small><strong>${stageState('kit').step}/8</strong></div><div class="stat"><small>Calzado</small><strong>${['cap','sole','shoe'].reduce((sum,k)=>sum+stageState(k).step,0)}/22</strong></div></div><div class="${completed?'good':'hint'}">${completed?'Has completado el recorrido industrial dentro de la plataforma.':'Aún puedes terminar las tres rutas industriales antes de generar el informe definitivo.'}</div><h3>2. Adjunta las versiones de Draw.io (opcional)</h3><p>Exporta tus diagramas como PNG desde Draw.io. Si los incorporas, aparecerán como anexos en tu informe Word.</p><div class="field"><label>Plano actual desde Draw.io (PNG)</label><input id="imgDrawA" type="file" accept="image/png"></div><div class="field"><label>Plano propuesto desde Draw.io (PNG)</label><input id="imgDrawB" type="file" accept="image/png"></div><div class="row"><span id="drawAFlag" class="pill">${images.drawA?'PNG actual cargado':'Sin PNG actual'}</span><span id="drawBFlag" class="pill">${images.drawB?'PNG propuesto cargado':'Sin PNG propuesto'}</span></div><button id="exportPrelim" class="btn line">↓ Descargar informe preliminar Word</button></div><div class="card stack"><h3>3. Explica tus decisiones</h3>${['¿Qué problemas identificaste en el recorrido actual?','¿Qué cambio propones y por qué?','¿Qué resultados medibles obtuviste?','¿Qué verificarías antes de llevar la propuesta a una planta real?'].map((x,i)=>`<div class="field"><label for="answer${i}">${i+1}. ${x}</label><textarea id="answer${i}" placeholder="Responde con argumentos y resultados...">${esc(S.answers[i])}</textarea></div>`).join('')}<div class="field"><label for="aiNotes">Revisión con IA y correcciones (opcional)</label><textarea id="aiNotes" placeholder="Qué sugirió, qué verificaste y qué corregiste...">${esc(S.aiNotes)}</textarea></div><button id="exportFinal" class="btn gold">↓ Descargar informe definitivo Word</button><div id="finalFeedback"></div></div></div><div class="card cream" style="margin-top:16px"><h3>¿Qué incluirá el documento?</h3><p>Identificación del estudiante, descripción de casos, diagrama del kit, plano industrial consolidado, plano propuesto, tabla de actividades, distancias calculadas, comparación, conclusiones y anexos PNG cargados desde Draw.io.</p><p class="tiny">Los avances de texto y recorridos se guardan en el navegador. Los archivos adjuntos en esta escena no se almacenan automáticamente en un servidor. Publicar la clase no guarda calificaciones.</p></div>`}
const SCENES=[s0,s1,s2,s3,s4,s5,s6,s7,s8,s9,s10,s11,s12,s13,s14];
function actOnArea(k,area){const cfg=STAGE_CFG[k],p=stageState(k),e=cfg.items[p.step];if(!e){showMsg('Esta ruta ya está completa.');return}if(e.place!==area){S.feedback=`Revisa ${e.id}. ${areaName(area,k)} no es la estación correcta para esta actividad. Lee el cursograma y vuelve a intentarlo.`;S.selectedStage=k;save();render();return}const mark={id:e.id,type:e.type,place:area,from:e.from,label:e.label,time:e.time};if(e.type==='T'){const line=calculatePath(e.id,p.waypoint,false,k==='kit'?'kit':'industrial');if(!line){S.feedback='No es posible construir un camino transitable con ese punto intermedio. Bórralo o selecciona otro lugar del pasillo.';S.selectedStage=k;save();render();return;}p.routes[e.id]=line;S.routeFocus=e.id;S.feedback=`Transporte ${e.id} trazado correctamente desde ${areaName(e.from,k)} hasta ${areaName(e.place,k)}. Distancia simulada: ${short(line.dist)} metros.`}else S.feedback=`Símbolo ${SYMBOLS[e.type]} colocado en ${areaName(area,k)}. Esta actividad no necesita transporte adicional.`;p.marks.push(mark);p.step++;p.waypoint=null;S.selectedStage=k;save();render();if(e.type==='T')playMotion(e.id)}
function areaName(id,k){return (k==='kit'?KIT_STATIONS:STATIONS)[id]?.name||id}
function placeWaypoint(k,ev){const p=stageState(k),item=STAGE_CFG[k].items[p.step];if(!item||item.type!=='T')return;const svg=ev.target.closest('svg'),r=svg.getBoundingClientRect(),vb=svg.viewBox.baseVal,scaleX=vb.width/r.width,scaleY=vb.height/r.height;const ox=k==='kit'?34:50,oy=k==='kit'?38:57,sc=k==='kit'?44:28;let x=Math.round(((ev.clientX-r.left)*scaleX-ox)/sc*2)/2,y=Math.round(((ev.clientY-r.top)*scaleY-oy)/sc*2)/2;const st=stationsFor(k==='kit'?'kit':'industrial');if(!pointIsFree(x,y,st,k==='kit'?12:30,k==='kit'?10:18)){S.feedback='Ese punto está dentro de un equipo o fuera del espacio transitable. Prueba sobre un pasillo.';S.selectedStage=k;render();return}p.waypoint=[x,y];S.feedback=`Punto de paso fijado en (${x} m, ${y} m). Ahora selecciona la estación de destino. Si deseas el camino más directo, pulsa «Borrar punto de paso».`;S.selectedStage=k;save();render()}
function undoStage(k){const p=stageState(k);if(!p.step)return;const last=p.marks.pop();if(last?.type==='T')delete p.routes[last.id];p.step--;p.waypoint=null;S.feedback=`Se retiró ${last?.id}. Puedes hacerlo nuevamente.`;S.selectedStage=k;save();render()}
function stageReview(k){const p=stageState(k),cfg=STAGE_CFG[k],pending=cfg.items.slice(p.step).map(x=>x.id);const trs=cfg.items.filter(x=>x.type==='T');const untr=trs.filter(x=>!p.routes[x.id]).map(x=>x.id);S.feedback=pending.length?`Faltan ${pending.length} actividades (${pending.slice(0,5).join(', ')}${pending.length>5?'…':''}). Transportes pendientes: ${untr.join(', ')||'ninguno'}.`:`¡Terminaste! Ubicaste ${cfg.items.length} actividades y ${trs.length} transportes. Distancia del recorrido en la simulación: ${short(stageTotal(k))} m.`;S.selectedStage=k;save();render()}
function playMotion(code){const path=document.getElementById('drawroute_'+code);if(!path)return;const svg=path.ownerSVGElement;if(!svg)return;document.getElementById('route-runner')?.remove();if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;let len;try{len=path.getTotalLength()}catch{return}const c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('id','route-runner');c.setAttribute('r','7');c.setAttribute('fill','#d6a84b');c.setAttribute('stroke','#112A46');c.setAttribute('stroke-width','2');c.setAttribute('pointer-events','none');svg.append(c);const start=performance.now(),duration=2000;function frame(time){if(!document.contains(c))return;const t=Math.min(1,(time-start)/duration);let p=path.getPointAtLength(len*t);c.setAttribute('cx',p.x);c.setAttribute('cy',p.y);if(t<1)animReq=requestAnimationFrame(frame)}animReq=requestAnimationFrame(frame)}
function replay(k){if(k==='consolidated'){const codes=Object.keys(allRoutes());if(!codes.length)return showMsg('Primero construye las rutas.');render();let i=0;const seq=()=>{if(S.scene!==10||i>=codes.length)return;playMotion(codes[i++]);if(i<codes.length)setTimeout(seq,2200)};seq()}else{const arr=Object.keys(stageState(k).routes);if(!arr.length)return showMsg('Primero dibuja un transporte.');render();playMotion(arr.at(-1))}}
function downloadBlob(blob,file){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=file;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),7000)}
function fname(str){return String(str||'Estudiante').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]/g,'_').slice(0,65)}
async function toPNG(svg){const clone=svg.replace(/<svg /,'<svg xmlns:xlink="http://www.w3.org/1999/xlink" ');const src=new Blob([clone],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(src);try{const img=await new Promise((resolve,reject)=>{let i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('No se pudo convertir el SVG a imagen.'));i.src=url});const can=document.createElement('canvas');can.width=(img.naturalWidth||1000)*2;can.height=(img.naturalHeight||700)*2;const ctx=can.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,can.width,can.height);ctx.drawImage(img,0,0);return await new Promise((yes,no)=>can.toBlob(b=>b?yes(b):no(Error('No se creó el PNG')),'image/png'))}finally{URL.revokeObjectURL(url)}}
async function exportDiagram(key){try{const k=key==='consolidated'?'cap':key==='proposed'?'cap':key;const options=key==='consolidated'?{merge:true}:key==='proposed'?{proposal:true}:{};if(key==='kit'&&stageState('kit').step!==8)throw Error('Completa primero las ocho actividades del kit.');const svg=diagramSVG(k,options),blob=await toPNG(svg);downloadBlob(blob,`Diagrama_${key}_${fname(S.name)}.png`);showMsg('Plano PNG descargado correctamente.')}catch(err){console.error(err);showMsg(err.message,true)}}
async function copyText(v){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(v)}else{const t=document.createElement('textarea');t.value=v;document.body.append(t);t.select();if(!document.execCommand('copy'))throw Error('No disponible');t.remove()}showMsg('Prompt copiado. Pégalo en tu herramienta de IA.')}catch{showMsg('Selecciona el texto del recuadro y cópialo manualmente.',true)}}
async function checkDrawio(file){if(!file)return;let feedback;try{if(file.size>8_000_000)throw Error('Este archivo supera el límite de 8 MB.');const raw=await file.text();let doc=new DOMParser().parseFromString(raw,'application/xml');if(doc.querySelector('parsererror'))throw Error('El XML de Draw.io tiene errores de sintaxis.');let cells=[...doc.querySelectorAll('mxGraphModel mxCell[vertex="1"]')],pages=doc.querySelectorAll('diagram').length;if(!cells.length&&pages){for(const d of doc.querySelectorAll('diagram')){const b64=(d.textContent||'').trim();if(!b64)continue;if(!('DecompressionStream' in window))throw Error('No es posible descomprimir este archivo en el navegador. Guarda Draw.io como XML no comprimido.');const packed=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));const stream=new Blob([packed]).stream().pipeThrough(new DecompressionStream('deflate-raw'));const inner=decodeURIComponent(new TextDecoder().decode(await new Response(stream).arrayBuffer()));const innerDoc=new DOMParser().parseFromString(inner,'application/xml');if(innerDoc.querySelector('parsererror'))throw Error('Una página interna tiene XML inválido.');cells.push(...innerDoc.querySelectorAll('mxCell[vertex="1"]'))}}if(!cells.length)throw Error('No se encontraron elementos reconocibles de un diagrama Draw.io.');const values=cells.map(c=>c.getAttribute('value')||'');const ids=Object.values(EVENTS).flat().map(x=>x[0]);const present=ids.filter(id=>values.some(v=>new RegExp('(^|[^A-Z0-9])'+id+'([^A-Z0-9]|$)','i').test(v)));const missing=ids.filter(id=>!present.includes(id));S.fileCheck=`Draw.io: ${pages} página(s), ${present.length}/22 códigos detectados como texto en objetos.`;feedback=`<div class="${missing.length?'hint':'good'}"><b>Archivo Draw.io reconocido.</b> ${present.length}/22 códigos de actividad detectados en objetos. ${missing.length?`No detectados: ${missing.join(', ')}.`:'Se reconocieron los 22 códigos.'}<br><b>Importante:</b> esto no verifica geométricamente la ubicación, el trazado, los símbolos ni las medidas. Comprueba visualmente tu archivo y utiliza el prompt de auditoría.</div>`}catch(e){S.fileCheck='Archivo Draw.io no validado';feedback=`<div class="bad">${esc(e.message)}</div>`}save();const out=document.getElementById('fileFeedback');if(out)out.innerHTML=feedback}
function valnum(x){const t=String(x??'').trim();if(!t)return null;const n=Number(t.replace(',','.'));return Number.isFinite(n)&&n>=0?n:null}
// Acciones de navegación y construcción.
document.getElementById('nav').addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)go(Number(b.dataset.go))});
document.getElementById('prev').addEventListener('click',()=>go(S.scene-1));document.getElementById('next').addEventListener('click',()=>go(S.scene+1));
document.getElementById('screen').addEventListener('click',async e=>{
 const element=e.target.closest('[data-area],[data-mapbg],[data-simple],[data-simplequiz],[data-measure],[data-quiz],[data-branches],[data-undo],[data-hint],[data-clearp],[data-review],[data-export],[data-play],[data-proposal],[data-prompt]');
 if(element){let ds=element.dataset;
  if(ds.area){const k=({4:'kit',7:'cap',8:'sole',9:'shoe'})[S.scene];if(k)actOnArea(k,ds.area);return}
  if(ds.mapbg){const k=({4:'kit',7:'cap',8:'sole',9:'shoe'})[S.scene];if(k)placeWaypoint(k,e);return}
  if(ds.simple!==undefined){S.intro=Number(ds.simple);save();render();return}
  if(ds.simplequiz){document.getElementById('simpleFeedback').innerHTML=ds.simplequiz==='no'?'Correcto: no hay transporte si el vaso permanece en el mismo lugar.':'Revisa: una inspección en el mismo lugar no obliga a dibujar una flecha.';return}
  if(ds.measure!==undefined){S.measure=Number(ds.measure);S.measureChecked=false;save();render();return}
  if(ds.quiz){const [i,j]=ds.quiz.split(':').map(Number);S.quiz[i]=j;save();render();return}
  if(ds.branches){document.getElementById('branchFeedback').innerHTML=`<div class="${ds.branches==='ok'?'good':'hint'}">${ds.branches==='ok'?'Correcto: son dos rutas paralelas que convergen en ensamble.':'Revisa el proceso: las dos ramas iniciales avanzan de forma independiente hasta ensamble.'}</div>`;return}
  if(ds.undo){undoStage(ds.undo);return}
  if(ds.hint){const item=STAGE_CFG[ds.hint].items[stageState(ds.hint).step];if(item)showMsg(item.type==='T'?`Origen: ${areaName(item.from,ds.hint)}. Destino: ${areaName(item.place,ds.hint)}.`:`Coloca el símbolo en ${areaName(item.place,ds.hint)}.`);return}
  if(ds.clearp){stageState(ds.clearp).waypoint=null;S.feedback='Punto intermedio borrado. Haz clic directamente en la estación de destino.';S.selectedStage=ds.clearp;save();render();return}
  if(ds.review){stageReview(ds.review);return}
  if(ds.export){await exportDiagram(ds.export);return}
  if(ds.play){replay(ds.play);return}
  if(ds.proposal){S.proposal=ds.proposal;save();render();return}
  if(ds.prompt){await copyText(PROMPTS[ds.prompt]);return}
 }
 const id=e.target.closest('button')?.id;if(!id)return;
 if(id==='start'){if(!ready())showMsg('Escribe tus nombres y apellidos.',true);else go(1)}
 if(id==='checkMeasure'){S.measureChecked=true;save();render()}
 if(id==='exportPrelim')await exportDOCX('prelim');
 if(id==='exportFinal')await exportDOCX('final');
});
document.getElementById('screen').addEventListener('keydown',e=>{const a=e.target.closest('[data-area]');if(a&&(e.key==='Enter'||e.key===' ')){e.preventDefault();const k=({4:'kit',7:'cap',8:'sole',9:'shoe'})[S.scene];if(k)actOnArea(k,a.dataset.area)}});
document.getElementById('screen').addEventListener('input',e=>{const a=e.target,k=a.id;if(k==='name')S.name=a.value;else if(k==='diagnosis'||k==='hypothesis'||k==='proposalText'||k==='aiNotes')S[k]=a.value;else if(/^answer[0-3]$/.test(k))S.answers[Number(k.slice(-1))]=a.value;save();if(k==='name')document.getElementById('topUser').textContent=ready()?S.name:'Aprendizaje aplicado'});
document.getElementById('screen').addEventListener('change',async e=>{const t=e.target;if(t.id==='drawioFile')return checkDrawio(t.files?.[0]);if(t.id==='imgDrawA'||t.id==='imgDrawB'){const k=t.id==='imgDrawA'?'drawA':'drawB',f=t.files?.[0];if(!f)return;if(f.size>7_000_000||f.type!=='image/png'){showMsg('Adjunta un PNG menor de 7 MB.',true);return;}images[k]=new Uint8Array(await f.arrayBuffer());const el=document.getElementById(k+'Flag');if(el)el.textContent='PNG cargado';showMsg('Imagen adjunta para el informe.')}});
